@page "/courses"
@inject CatalogService CatalogService
@rendermode InteractiveServer

<PageTitle>Course Catalog</PageTitle>

<h1>Course Catalog</h1>

<div class="row mb-3">
    <div class="col-md-6">
        <input type="text" class="form-control" placeholder="Search courses..." @bind="searchTerm" @bind:event="oninput" />
    </div>
    <div class="col-md-4">
        <select class="form-select" @bind="selectedDepartmentId">
            <option value="0">All Departments</option>
            @foreach (var dept in departments)
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>
    </div>
</div>

<table class="table table-striped">
    <thead>
        <tr>
            <th>Code</th>
            <th>Title</th>
            <th>Department</th>
            <th>Credits</th>
            <th>Instructor</th>
            <th></th>
        </tr>
    </thead>
    <tbody>
        @foreach (var course in filteredCourses)
        {
            <tr>
                <td>@course.CourseCode</td>
                <td>@course.Title</td>
                <td>@course.DepartmentName</td>
                <td>@course.Credits</td>
                <td>@course.InstructorName</td>
                <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
            </tr>
        }
    </tbody>
</table>

@if (!filteredCourses.Any())
{
    <p class="text-muted">No courses match your search criteria.</p>
}

@code {
    [SupplyParameterFromQuery] public int? departmentId { get; set; }

    private string searchTerm = string.Empty;
    private int selectedDepartmentId;
    private List<Department> departments = new();
    private List<Course> filteredCourses = new();

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        if (departmentId.HasValue)
            selectedDepartmentId = departmentId.Value;
        UpdateCourses();
    }

    private int _previousDepartmentId;
    private string _previousSearchTerm = string.Empty;

    protected override void OnAfterRender(bool firstRender)
    {
        if (_previousDepartmentId != selectedDepartmentId || _previousSearchTerm != searchTerm)
        {
            _previousDepartmentId = selectedDepartmentId;
            _previousSearchTerm = searchTerm;
            UpdateCourses();
            StateHasChanged();
        }
    }

    private void UpdateCourses()
    {
        int? deptFilter = selectedDepartmentId > 0 ? selectedDepartmentId : null;
        filteredCourses = CatalogService.GetCourses(searchTerm, deptFilter);
    }
}

@page "/enroll"
@inject CatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>
<p>Complete the form below to submit an enrollment request.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Request Submitted!</h4>
        <p>Your enrollment request has been submitted successfully. You will receive a confirmation via your student email.</p>
        <a href="courses" class="btn btn-primary">Browse More Courses</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-md-6">
            <form method="post" @formname="enrollment" @onsubmit="HandleSubmit">
                <AntiforgeryToken />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name</label>
                    <input type="text" class="form-control" id="studentName" name="StudentName"
                           @bind="request.StudentName" required />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <input type="text" class="form-control" id="studentId" name="StudentId"
                           @bind="request.StudentId" required placeholder="e.g., STU-12345" />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <select class="form-select" id="courseId" name="CourseId" @bind="request.CourseId" required>
                        <option value="0" disabled>Select a course...</option>
                        @foreach (var course in courses)
                        {
                            <option value="@course.Id">@course.CourseCode — @course.Title</option>
                        }
